<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ApiError } from '@/api/client'
import type { CatalogEntry, Edition } from '@/api/catalog'
import type { InventoryItem } from '@/api/inventory'
import { useCatalogStore } from '@/stores/catalog'
import { useCollectionsStore } from '@/stores/collections'
import { useInventoryStore } from '@/stores/inventory'
const route=useRoute();const collections=useCollectionsStore();const inventory=useInventoryStore();const catalog=useCatalogStore();const editions=ref<(Edition&{title:string})[]>([]);const adding=ref(false);const editing=ref<number|null>(null);const deleting=ref<number|null>(null);const error=ref('');const form=ref({edition_id:'',condition:'',notes:''});const id=computed(()=>Number(route.params.collectionId));const canEdit=computed(()=>['owner','admin','editor'].includes(collections.collection?.role??''))
function message(cause:unknown){if(cause instanceof ApiError){if(cause.status===403)return 'You do not have permission for this action.';if(cause.status===404)return 'This inventory item is no longer available.';if(cause.status===409)return 'This change conflicts with existing data.';if(cause.status===422)return 'Check the entered physical copy details.'}return 'This action could not be completed. Please try again.'}
async function load(){error.value='';await collections.loadCollection(id.value);if(!collections.collection)return;await Promise.all([inventory.load(id.value),catalog.load(id.value)]);try{const groups=await Promise.all(catalog.entries.map(async(entry:CatalogEntry)=>({entry,editions:await catalog.listEditions(id.value,entry.id)})));editions.value=groups.flatMap(({entry,editions})=>editions.map(edition=>({...edition,title:entry.display_title})))}catch(cause){error.value=message(cause)}}
watch(()=>route.params.collectionId,load,{immediate:true})
function reset(){form.value={edition_id:'',condition:'',notes:''}}
function beginAdd(){error.value='';editing.value=null;deleting.value=null;reset();adding.value=true}
function beginEdit(item:InventoryItem){error.value='';adding.value=false;deleting.value=null;editing.value=item.id;form.value={edition_id:String(item.edition_id),condition:item.condition??'',notes:item.notes??''}}
async function create(){const editionId=Number(form.value.edition_id);if(!editionId){error.value='Choose an edition.';return}try{const item=await inventory.createInventoryItem(id.value,{edition_id:editionId,condition:form.value.condition.trim()||null,notes:form.value.notes.trim()||null});inventory.items.push(item);adding.value=false;reset()}catch(cause){error.value=message(cause)}}
async function save(itemId:number){try{const item=await inventory.updateInventoryItem(id.value,itemId,{condition:form.value.condition.trim()||null,notes:form.value.notes.trim()||null});const index=inventory.items.findIndex(candidate=>candidate.id===itemId);if(index>=0)inventory.items.splice(index,1,item);editing.value=null}catch(cause){error.value=message(cause)}}
async function remove(itemId:number){try{await inventory.deleteInventoryItem(id.value,itemId);inventory.items=inventory.items.filter(item=>item.id!==itemId);deleting.value=null}catch(cause){error.value=message(cause)}}
function edition(item:InventoryItem){return editions.value.find(candidate=>candidate.id===item.edition_id)}
</script>
<template><section class="page-content" aria-labelledby="inventory-heading"><RouterLink class="back-link" :to="{name:'collection-detail',params:{collectionId:id}}">← Collection details</RouterLink><p v-if="collections.detailLoading||inventory.loading" role="status">Loading inventory…</p><div v-else-if="collections.detailError||inventory.error" class="empty-state state-error" role="alert"><h1>Inventory unavailable</h1><p>This collection or its inventory is no longer available to you.</p></div><template v-else-if="collections.collection"><div class="page-heading"><div><p class="eyebrow">Physical copies <span class="role-pill">{{collections.collection.role}}</span></p><h1 id="inventory-heading">Inventory</h1></div><button v-if="canEdit" @click="beginAdd">Add physical copy</button></div><p v-if="error" class="form-error" role="alert">{{error}}</p><form v-if="adding" class="collection-form panel" @submit.prevent="create"><h2>Add physical copy</h2><label>Edition<select v-model="form.edition_id" required><option disabled value="">Choose an edition</option><option v-for="edition in editions" :key="edition.id" :value="String(edition.id)">{{edition.title}} — {{edition.display_name}}</option></select></label><label>Condition <span class="optional">optional</span><input v-model="form.condition" /></label><label>Notes <span class="optional">optional</span><textarea v-model="form.notes" /></label><div class="action-row"><button>Create physical copy</button><button type="button" class="button-secondary" @click="adding=false">Cancel</button></div></form><div v-if="!inventory.items.length" class="empty-state"><h2>No physical copies yet</h2><p v-if="canEdit">Add physical copies to track the editions you own.</p><p v-else>No physical copies have been added to this collection.</p></div><ul v-else class="inventory-list" aria-label="Physical copies"><li v-for="item in inventory.items" :key="item.id" class="panel"><h2>{{edition(item)?.title??'Unavailable title'}}</h2><p><strong>Edition:</strong> {{edition(item)?.display_name??'Unavailable edition'}}</p><p v-if="item.condition"><strong>Condition:</strong> {{item.condition}}</p><p v-if="item.notes"><strong>Notes:</strong> {{item.notes}}</p><p><strong>Location:</strong> {{item.location_id===null?'Unassigned':'Assigned'}}</p><div v-if="canEdit" class="action-row"><button :aria-label="`Edit physical copy ${item.id}`" @click="beginEdit(item)">Edit copy</button><button class="button-danger" :aria-label="`Delete physical copy ${item.id}`" @click="deleting=item.id">Delete copy</button></div><form v-if="editing===item.id" class="collection-form" @submit.prevent="save(item.id)"><h3>Edit physical copy</h3><label>Condition <input v-model="form.condition" /></label><label>Notes <textarea v-model="form.notes" /></label><div class="action-row"><button>Save copy</button><button type="button" class="button-secondary" @click="editing=null">Cancel</button></div></form><section v-if="deleting===item.id" class="confirmation" :aria-labelledby="`delete-copy-${item.id}`"><h3 :id="`delete-copy-${item.id}`">Delete this physical copy?</h3><p>This deletes only this copy. Its catalog entry, edition, identifiers, and other copies remain.</p><div class="action-row"><button class="button-danger" @click="remove(item.id)">Confirm delete copy</button><button class="button-secondary" @click="deleting=null">Cancel</button></div></section></li></ul></template></section></template>
